-- =============================================================================
-- OSRAM Thailand Catalog — seed data (migration 2 of 2)
-- Applied automatically after 20260101000000_initial_schema.sql via the
-- Supabase GitHub integration — no manual step needed.
-- Safe to re-run: categories upsert by key, products upsert by (category_key, code).
-- =============================================================================

on conflict (key) do update set
  name = excluded.name, name_en = excluded.name_en, tagline = excluded.tagline,
  specs_common = excluded.specs_common, base = excluded.base, warranty = excluded.warranty,
  sort_order = excluded.sort_order;

on conflict (category_key, code) do update set
  model = excluded.model, w = excluded.w, retrofit = excluded.retrofit, lm = excluded.lm,
  v = excluded.v, cctcode = excluded.cctcode, dim = excluded.dim, cutout = excluded.cutout,
  pack = excluded.pack, material = excluded.material, mount = excluded.mount, color = excluded.color,
  series = excluded.series, tube = excluded.tube, solar = excluded.solar, battery = excluded.battery,
  note = excluded.note;

