insert into categories (key, name, name_en, tagline, specs_common, base, warranty, sort_order)
values
  ('led-bulb', 'หลอด LED บัลบ์', 'LED Bulb', 'หลอดไฟทรงบัลบ์มาตรฐาน ใช้งานทั่วไปในบ้านและร้านค้า', '{"ขั้วหลอด": "E27", "IP": "IP20", "อายุการใช้งาน": "17,520 ชม.", "CRI": "≥80", "การรับประกัน": "1 ปี"}'::jsonb, 'E27', '1 ปี', 0),
  ('t-bulb', 'หลอด LED ทรงตอ (T Bulb)', 'T Bulb', 'กำลังส่องสว่างสูง ทดแทนหลอดฟลูออเรสเซนต์ในโรงงาน โกดัง', '{"ขั้วหลอด": "E27", "IP": "IP20", "อายุการใช้งาน": "17,520 ชม.", "CRI": "≥80", "CCT": "6500K", "การรับประกัน": "1 ปี"}'::jsonb, 'E27', '1 ปี', 1),
  ('led-stick-bulb', 'หลอด LED ทรงแท่ง (Stick Bulb)', 'LED Stick Bulb', 'ทรงเพรียว กะทัดรัด ให้แสงกระจายกว้างขึ้น 40%', '{"ขั้วหลอด": "E27", "IP": "IP20", "อายุการใช้งาน": "15,000 ชม.", "CRI": "≥80", "การรับประกัน": "1 ปี"}'::jsonb, 'E27', '1 ปี', 2),
  ('led-filament', 'หลอด LED ฟิลาเมนต์', 'LED Filament', 'ดีไซน์วินเทจ ทดแทนหลอดไส้ ประหยัดพลังงาน 85%', '{"ขั้วหลอด": "E27", "IP": "IP20", "อายุการใช้งาน": "15,000 ชม.", "CRI": "≥80", "CCT": "2700K", "การรับประกัน": "1 ปี"}'::jsonb, 'E27', '1 ปี', 3),
  ('gu10', 'สปอตไลท์ GU10 (PAR16/MR16)', 'GU10', 'ทดแทนหลอดฮาโลเจน 35-75W ประหยัดไฟ 85%', '{"ขั้วหลอด": "GU10", "IP": "IP20", "การรับประกัน": "1 ปี"}'::jsonb, 'GU10', '1 ปี', 4),
  ('t8-tube', 'หลอด LED T8', 'T8 Tube', 'ทดแทนหลอดฟลูออเรสเซนต์ T8 แสงสว่างสม่ำเสมอ ไม่กระพริบ', '{"ขั้วหลอด": "G13", "IP": "IP20", "อายุการใช้งาน": "25,000 ชม.", "CRI": "≥80", "การรับประกัน": "2 ปี"}'::jsonb, 'G13', '2 ปี', 5),
  ('led-strips', 'ไฟเส้น LED (LED Strips)', 'LED Strips', 'ไฟเส้นแสงสม่ำเสมอ ยืดหยุ่นสูง ติดตั้งง่าย มีทั้งรุ่น IP65 กันน้ำ', '{"CRI": "≥80", "อายุการใช้งาน": "15,000 ชม.", "การรับประกัน": "1 ปี"}'::jsonb, 'ไม่มีขั้ว (ไฟเส้น)', '1 ปี', 6),
  ('track-light-tr', 'โคมไฟราง หมุนได้ (Track Light TR)', 'Track Light TR', 'หมุนได้ 330° ใช้เน้นสินค้าในร้านค้าและโชว์รูม', '{"IP": "IP20", "CRI": "≥90", "อายุการใช้งาน": "30,000 ชม.", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 7),
  ('track-light-sf', 'โคมไฟสปอตไลท์ ติดเพดาน (Track Light SF)', 'Track Light SF', 'ติดตั้งแบบยึดเพดานโดยตรง แสงสม่ำเสมอ ไม่กระพริบ', '{"IP": "IP20", "CRI": "≥90", "อายุการใช้งาน": "30,000 ชม.", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 8),
  ('downlight', 'ดาวน์ไลท์ (Downlight)', 'Downlight', 'ดีไซน์ทันสมัย ค่า CRI สูง ลดแสงจ้า (UGR<16)', '{"IP": "IP20", "CRI": "≥90", "อายุการใช้งาน": "25,000-50,000 ชม.", "การรับประกัน": "2 ปี", "ติดตั้ง": "ฝังฝ้า (Recessed)"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 9),
  ('downlight-slim', 'ดาวน์ไลท์บาง ทรงกลม (Downlight Slim)', 'Downlight Slim', 'ทรงบางพิเศษ ตัวโคมทำจาก PC เบาแต่ทนทาน ติดฝ้ายิปซัมได้ลงตัว', '{"IP": "IP20", "CRI": "≥80", "อายุการใช้งาน": "25,000-50,000 ชม.", "การรับประกัน": "2 ปี", "ติดตั้ง": "ฝังฝ้า (Recessed)"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 10),
  ('downlight-slim-sq', 'ดาวน์ไลท์บาง ทรงเหลี่ยม (Downlight Slim SQ)', 'Downlight Slim Square', 'ทรงเหลี่ยมบางพิเศษ เหมาะกับฝ้าลายเส้นตรง', '{"IP": "IP20", "CRI": "≥80", "อายุการใช้งาน": "25,000-50,000 ชม.", "การรับประกัน": "2 ปี", "ติดตั้ง": "ฝังฝ้า (Recessed)"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 11),
  ('downlight-ceiling', 'ดาวน์ไลท์ติดลอย (Downlight Ceiling)', 'Downlight Ceiling', 'ไม่ต้องเจาะฝ้า ติดตั้งบนผิวเพดานได้ทันที', '{"IP": "IP20", "CRI": "≥80", "อายุการใช้งาน": "30,000 ชม.", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 12),
  ('panel-light', 'โคมไฟพาแนล (Panel Light)', 'Panel Light', 'แสงนุ่มนวล สม่ำเสมอ ประสิทธิภาพสูงถึง 120 lm/W เหมาะกับฝ้า T-bar', '{"IP": "IP20", "CRI": "≥80", "อายุการใช้งาน": "30,000 ชม.", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 13),
  ('ceiling-light', 'โคมเพดาน (Ceiling Light)', 'Ceiling Light', 'ดีไซน์ทันสมัย ทนแรงกระแทก IK06 มีทั้งทรงกลมและทรงรี', '{"IP": "IP65", "CRI": "≥80", "อายุการใช้งาน": "30,000 ชม.", "การรับประกัน": "2 ปี", "ทนแรงกระแทก": "IK06"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 14),
  ('table-lamp', 'โคมไฟตั้งโต๊ะ (Table Lamp)', 'Table Lamp', 'ปรับได้ 3 โทนสี ฟิล์มลดแสงจ้า เหมาะกับโต๊ะทำงานและโต๊ะอ่านหนังสือ', '{"IP": "IP20", "CRI": "≥95", "อายุการใช้งาน": "25,000 ชม.", "การรับประกัน": "2 ปี", "โหมดแสง": "3000K/4000K/5000K ปรับหรี่ได้"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 15),
  ('damp-proof-batten-light', 'โคมไฟกันน้ำ ในตัว (Damp Proof Batten Light)', 'Damp Proof Batten Light', 'IP65 กันฝุ่นกันน้ำ เหมาะกับโรงงาน โกดัง งานภายนอก', '{"IP": "IP65", "อายุการใช้งาน": "30,000 ชม.", "ทนแรงกระแทก": "IK08", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 16),
  ('damp-proof-batten', 'โคมกันน้ำ แบบโครง (Damp Proof Batten Housing)', 'Damp Proof Batten Housing', 'โครงโคมเปล่า IP65 รองรับหลอด T8 G13 (ไม่รวมหลอด)', '{"IP": "IP65", "v": "220-240V", "material": "ABS/PC/Aluminum", "mount": "Surface-mounted"}'::jsonb, 'G13 (โครงเปล่า)', NULL, 17),
  ('highbay-light', 'โคมไฮเบย์ (Highbay Light)', 'Highbay Light', 'แสงสว่างสูง กันฝุ่นกันน้ำ IP65 เหมาะกับโรงงาน คลังสินค้า อาคารสูง', '{"IP": "IP65", "ทนแรงกระแทก": "IK08", "อายุการใช้งาน": "50,000 ชม.", "CRI": "≥80", "การรับประกัน": "3 ปี"}'::jsonb, 'ในตัว (Integrated)', '3 ปี', 18),
  ('floodlight', 'สปอตไลท์ฟลัด (Floodlight)', 'Floodlight', 'กันน้ำกันฝุ่นมาตรฐาน IP66 บางเฉียบ ทนสภาพอากาศ เหมาะกับสนามกีฬาและป้ายโฆษณา', '{"IP": "IP66", "ทนแรงกระแทก": "IK08", "อายุการใช้งาน": "30,000 ชม.", "CRI": "≥80", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 19),
  ('street-light', 'โคมไฟถนน (Street Light)', 'Street Light', 'ป้องกันไฟกระชาก 6kV ตัวโคมอลูมิเนียมคุณภาพสูง ติดตั้งง่ายพร้อมสายไฟในตัว', '{"IP": "IP66", "ทนแรงกระแทก": "IK08", "อายุการใช้งาน": "30,000 ชม.", "CRI": "≥80", "CCT": "6500K", "การรับประกัน": "2 ปี"}'::jsonb, 'ในตัว (Integrated)', '2 ปี', 20),
  ('street-light-solar', 'โคมไฟถนนโซล่าเซลล์ (Street Light Solar)', 'Street Light Solar', 'ออลอินวัน แผงโซล่า+แบตเตอรี่ในตัว ไม่มีค่าไฟ ติดตั้งง่าย', '{"IP": "IP66", "ทนแรงกระแทก": "IK08", "อายุการใช้งาน": "50,000 ชม.", "CRI": "≥80", "CCT": "6500K", "การรับประกัน": "3 ปี"}'::jsonb, 'ในตัว (Integrated)', '3 ปี', 21),
  ('floodlight-solar', 'สปอตไลท์โซล่าเซลล์ (Flood Light Solar)', 'Flood Light Solar', 'แผงโซล่าแยก รีโมทควบคุม กันน้ำ IP66 ไม่มีค่าไฟ', '{"IP": "IP66", "ทนแรงกระแทก": "IK08", "อายุการใช้งาน": "50,000 ชม.", "CRI": "≥80", "การรับประกัน": "3 ปี"}'::jsonb, 'ในตัว (Integrated)', '3 ปี', 22)
